import sympy
from sympy.ntheory import factorint
from sympy.abc import x, y, z

CONDITION_LABELS = [
    "H_1: R is a Unique Factorization Domain",
    "H_2: a is a non-zero non-unit element of R",
    "¬Q: The radical of the principal ideal (a) is NOT the principal ideal generated by the product p_1 p_2 ... p_n"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    # Setup: witness can be `a` or `(a, p_list)`
    try:
        if isinstance(witness, tuple) and len(witness) == 2:
            a, p_list = witness
        else:
            a = witness
            p_list = None
    except Exception:
        return [False, False, False]

    # H1: R is a UFD (we support Z and polynomial rings over fields/Z)
    try:
        if isinstance(a, (int, sympy.Integer)):
            h1 = True
            is_poly = False
        elif isinstance(a, sympy.Expr):
            h1 = True
            is_poly = True
        else:
            h1 = False
            is_poly = False
            
        if h1 and p_list is not None:
            if not isinstance(p_list, (list, tuple)):
                h1 = False
            else:
                if not is_poly:
                    if not all(isinstance(p, (int, sympy.Integer)) for p in p_list):
                        h1 = False
                else:
                    if not all(isinstance(p, (int, sympy.Integer, sympy.Expr)) for p in p_list):
                        h1 = False
    except Exception:
        h1 = False
        is_poly = False

    # H2: a is a non-zero non-unit element of R
    try:
        if not h1:
            h2 = False
        elif not is_poly:
            a_val = int(a)
            h2 = (a_val != 0) and (abs(a_val) != 1)
        else:
            if a.is_zero:
                h2 = False
            else:
                free_symbols = a.free_symbols
                if not free_symbols:
                    # Constants in Q are units, constants in Z (except 1, -1) are non-units.
                    if isinstance(a, sympy.Rational) and not isinstance(a, sympy.Integer):
                        h2 = False
                    else:
                        try:
                            h2 = (abs(int(a)) != 1)
                        except Exception:
                            h2 = False
                else:
                    h2 = True
    except Exception:
        h2 = False

    # Auto-generate p_list (prime factors with multiplicity) if not provided
    try:
        if h1 and h2 and p_list is None:
            if not is_poly:
                a_val = int(a)
                factors = factorint(abs(a_val))
                p_list = []
                for p, e in factors.items():
                    p_list.extend([p] * e)
            else:
                factors = sympy.factor_list(a)
                p_list = []
                for f, e in factors[1]:
                    p_list.extend([f] * e)
    except Exception:
        if p_list is None:
            p_list = []

    # Conclusion: The radical of (a) is generated by the product p_1 p_2 ... p_n
    try:
        if not h1 or not h2:
            neg_q = False
        else:
            if not is_poly:
                a_val = int(a)
                factors = factorint(abs(a_val))
                rad_gen = 1
                for p in factors.keys():
                    rad_gen *= p
                
                prod_p = 1
                for p in p_list:
                    prod_p *= int(p)
                
                # In Z, ideals are equal iff their generators have the same absolute value
                q = (abs(rad_gen) == abs(prod_p))
                neg_q = not q
            else:
                rad_gen = sympy.sqf_part(a)
                prod_p = 1
                for p in p_list:
                    prod_p *= p
                
                if rad_gen == 0 or prod_p == 0:
                    q = (rad_gen == prod_p)
                else:
                    # In polynomial rings, ideals are equal iff generators divide each other
                    div1 = sympy.cancel(rad_gen / prod_p)
                    div2 = sympy.cancel(prod_p / rad_gen)
                    q = div1.is_constant() and div2.is_constant()
                neg_q = not q
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]